"""Value semantics for minisql.

This module is the single source of truth for NULL propagation, type
checking, operators, scalar functions, and aggregate functions.  Every
public function raises :class:`~minisql.errors.QueryError` for invalid
input.  The execution engine supplies already-evaluated Python values:
``None`` for NULL, ``bool``, ``int``, ``float``, or ``str``.
"""

from __future__ import annotations

import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, List

from .errors import QueryError

AGGREGATE_NAMES = frozenset({"count", "sum", "avg", "min", "max"})

# name -> (minimum arguments, maximum arguments or None for unlimited)
_SCALAR_ARITY = {
    "lower": (1, 1),
    "upper": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "round": (1, 2),
    "coalesce": (1, None),
}


# ---------------------------------------------------------------------------
# Type predicates
# ---------------------------------------------------------------------------


def is_number(value: Any) -> bool:
    """True for int/float but not bool (bool is a subclass of int)."""

    return isinstance(value, (int, float)) and not isinstance(value, bool)


def is_bool(value: Any) -> bool:
    return isinstance(value, bool)


def is_text(value: Any) -> bool:
    return isinstance(value, str)


def _category(value: Any) -> str:
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "text"
    raise QueryError("unsupported value type: %s" % type(value).__name__)


# ---------------------------------------------------------------------------
# Three-valued logic
# ---------------------------------------------------------------------------


def as_bool(value: Any) -> Any:
    """Coerce a value used as a condition to True/False/NULL.

    Anything other than a boolean or NULL is an error.
    """

    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError("expected a boolean value")


def sql_not(value: Any) -> Any:
    value = as_bool(value)
    if value is None:
        return None
    return not value


def sql_and(left: Any, right: Any) -> Any:
    left = as_bool(left)
    right = as_bool(right)
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def sql_or(left: Any, right: Any) -> Any:
    left = as_bool(left)
    right = as_bool(right)
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


# ---------------------------------------------------------------------------
# Arithmetic and concatenation
# ---------------------------------------------------------------------------


def negate(value: Any) -> Any:
    if value is None:
        return None
    if not is_number(value):
        raise QueryError("cannot negate a non-number")
    return -value


def arithmetic(op: str, left: Any, right: Any) -> Any:
    """Evaluate ``left op right`` for ``+``, ``-``, ``*``, or ``/``."""

    if op not in ("+", "-", "*", "/"):
        raise QueryError("unknown arithmetic operator: %s" % op)
    if left is None or right is None:
        return None
    if not is_number(left) or not is_number(right):
        raise QueryError("arithmetic requires numbers")

    if op == "/":
        if right == 0:
            return None
        return left / right

    if isinstance(left, int) and isinstance(right, int):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right

    left = float(left)
    right = float(right)
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    return left * right


