# ---------------------------------------------------------------------------


def order_compare(left: Any, right: Any) -> int:
    """Three-way comparison of two non-NULL values.

    Numbers compare numerically, strings by code point, and booleans with
    booleans.  Comparing values of different categories is an error.
    """

    if left is None or right is None:
        raise QueryError("cannot order NULL values")

    left_cat = _category(left)
