    if any(arg is None for arg in args):
        return None

    first = args[0]
    if name == "lower":
        if not isinstance(first, str):
            raise QueryError("LOWER requires a string")
        return first.lower()
    if name == "upper":
        if not isinstance(first, str):
            raise QueryError("UPPER requires a string")
        return first.upper()
    if name == "length":
        if not isinstance(first, str):
            raise QueryError("LENGTH requires a string")
        return len(first)
    if name == "abs":
        if not is_number(first):
            raise QueryError("ABS requires a number")
        return abs(first)
    # ROUND
    if not is_number(first):
        raise QueryError("ROUND requires a number")
    if len(args) == 1:
        return _round(first)
    digits = args[1]
    if not isinstance(digits, int) or isinstance(digits, bool):
        raise QueryError("ROUND's second argument must be an integer")
    return _round(first, digits)


# ---------------------------------------------------------------------------
# Aggregate functions
# ---------------------------------------------------------------------------


def aggregate_call(name: str, values: List[Any]) -> Any:
    """Evaluate an aggregate over ``values`` (which may contain NULLs)."""

    name = name.lower()
    if name not in AGGREGATE_NAMES:
        raise QueryError("unknown aggregate: %s" % name)

    non_null = [value for value in values if value is not None]
